  7→/// Displays progress for a step execution.
  8→pub struct StepProgress {
  9→    name: String,
 10→    description: String,
 11→    spinner: Option<Box<dyn SpinnerHandle>>,
 12→    start_time: Instant,
 13→    theme: BivvyTheme,
 14→}
 15→
 16→impl StepProgress {
 17→    /// Create a new step progress display.
 18→    pub fn new(name: &str, description: &str, show_spinner: bool) -> Self {
 19→        let spinner = if show_spinner {
 20→            Some(
 21→                Box::new(ProgressSpinner::new(&format!("{} - {}", name, description)))
 22→                    as Box<dyn SpinnerHandle>,
 23→            )
 24→        } else {
 25→            None
 26→        };
 27→
 28→        Self {
 29→            name: name.to_string(),
 30→            description: description.to_string(),
 31→            spinner,
 32→            start_time: Instant::now(),
 33→            theme: BivvyTheme::new(),
 34→        }
 35→    }
 36→
 37→    /// Create without spinner (for quiet/silent modes).
 38→    pub fn quiet(name: &str, description: &str) -> Self {
 39→        Self::new(name, description, false)
 40→    }
 41→
 42→    /// Update the progress message.
 43→    pub fn update(&mut self, msg: &str) {
 44→        if let Some(spinner) = &mut self.spinner {
 45→            spinner.set_message(msg);
 46→        }
 47→    }
 48→
 49→    /// Mark as successful.
 50→    pub fn success(mut self) {
 51→        let duration = self.start_time.elapsed();
 52→        let msg = format!(
 53→            "{} - {} ({})",
 54→            self.name,
 55→            self.description,
 56→            format_duration(duration)
 57→        );
 58→
 59→        if let Some(mut spinner) = self.spinner.take() {
 60→            spinner.finish_success(&msg);
 61→        } else {
 62→            println!("{}", self.theme.format_success(&msg));
 63→        }
 64→    }
 65→
 66→    /// Mark as failed.
 67→    pub fn error(mut self, error: &str) {
 68→        let msg = format!("{} - {}", self.name, error);
 69→
 70→        if let Some(mut spinner) = self.spinner.take() {
 71→            spinner.finish_error(&msg);
 72→        } else {
 73→            println!("{}", self.theme.format_error(&msg));
 74→        }
 75→    }
 76→
 77→    /// Mark as skipped.
 78→    pub fn skipped(mut self, reason: &str) {
 79→        let msg = format!("{} - {}", self.name, reason);
 80→
 81→        if let Some(mut spinner) = self.spinner.take() {
 82→            spinner.finish_skipped(&msg);
 83→        } else {
 84→            println!("○ {}", msg);
 85→        }
 86→    }
 87→
 88→    /// Get elapsed duration.
 89→    pub fn elapsed(&self) -> Duration {
 90→        self.start_time.elapsed()
 91→    }
 92→}
 93→
 94→/// Format a timestamp as a relative time string (e.g., "2 minutes ago").
 95→pub fn format_relative_time(timestamp: chrono::DateTime<chrono::Utc>) -> String {
 96→    let now = chrono::Utc::now();
 97→    let diff = now.signed_duration_since(timestamp);
 98→    let seconds = diff.num_seconds();
 99→
100→    if seconds < 0 {
101→        return "just now".to_string();
102→    }
103→
104→    if seconds < 60 {
105→        return "just now".to_string();
106→    }
107→
108→    let minutes = seconds / 60;
109→    if minutes < 60 {
110→        return if minutes == 1 {
111→            "1 minute ago".to_string()
112→        } else {
113→            format!("{} minutes ago", minutes)
114→        };
115→    }
116→
117→    let hours = minutes / 60;
118→    if hours < 24 {
119→        return if hours == 1 {
120→            "1 hour ago".to_string()
121→        } else {
122→            format!("{} hours ago", hours)
123→        };
124→    }
125→
126→    let days = hours / 24;
127→    if days < 30 {
128→        return if days == 1 {
129→            "yesterday".to_string()
130→        } else {
131→            format!("{} days ago", days)
132→        };
133→    }
134→
135→    let months = days / 30;
136→    if months < 12 {
137→        return if months == 1 {
138→            "1 month ago".to_string()
139→        } else {
140→            format!("{} months ago", months)
141→        };
142→    }
143→
144→    let years = months / 12;
145→    if years == 1 {
146→        "1 year ago".to_string()
147→    } else {
148→        format!("{} years ago", years)
149→    }
150→}
151→
152→/// Format a duration for display.
153→pub fn format_duration(d: Duration) -> String {
154→    let secs = d.as_secs_f64();
155→    if secs < 1.0 {
156→        format!("{}ms", d.as_millis())
157→    } else if secs < 60.0 {
158→        format!("{:.1}s", secs)
159→    } else {
160→        let mins = secs / 60.0;
161→        format!("{:.1}m", mins)
162→    }
163→}
