 29→/// Maximum total execution attempts per step (auto-retries + manual retries).
 30→/// Prevents infinite loops when the recovery prompt always returns "retry"
 31→/// (e.g., in test environments with MockUI).
 32→const MAX_STEP_ATTEMPTS: u32 = 100;
 33→
 34→/// Progress events emitted during workflow execution.
 35→#[derive(Debug)]
 36→pub enum RunProgress<'a> {
 37→    /// A step is about to start.
 38→    StepStarting {
 39→        name: &'a str,
 40→        index: usize,
 41→        total: usize,
 42→    },
 43→    /// A step finished.
 44→    StepFinished {
 45→        name: &'a str,
 46→        result: &'a StepResult,
 47→    },
 48→    /// A step was skipped.
 49→    StepSkipped { name: &'a str },
 50→}
 51→
 52→/// Orchestrates the execution of a workflow.
 53→pub struct WorkflowRunner<'a> {
 54→    config: &'a BivvyConfig,
 55→    steps: HashMap<String, ResolvedStep>,
 56→}
 57→
 58→/// Result of running a workflow.
 59→#[derive(Debug)]
 60→pub struct WorkflowResult {
 61→    /// Workflow name.
 62→    pub workflow: String,
 63→    /// Results from each executed step.
 64→    pub steps: Vec<StepResult>,
 65→    /// Names of skipped steps.
 66→    pub skipped: Vec<String>,
 67→    /// Total duration.
 68→    pub duration: Duration,
 69→    /// Whether all steps succeeded.
 70→    pub success: bool,
 71→    /// Whether the workflow was aborted by the user during recovery.
 72→    pub aborted: bool,
 73→}
 74→
 75→/// Options for running a workflow.
 76→#[derive(Debug, Default)]
 77→pub struct RunOptions {
 78→    /// Workflow name (defaults to "default").
 79→    pub workflow: Option<String>,
 80→    /// Only run these steps.
 81→    pub only: HashSet<String>,
 82→    /// Skip these steps.
 83→    pub skip: HashSet<String>,
 84→    /// How to handle skipped step dependencies.
 85→    pub skip_behavior: SkipBehavior,
 86→    /// Force re-run these steps even if complete.
 87→    pub force: HashSet<String>,
 88→    /// Dry run mode.
 89→    pub dry_run: bool,
 90→    /// Requirements that are provided by the environment and should skip gap checks.
 91→    pub provided_requirements: HashSet<String>,
 92→    /// Active environment name for only_environments filtering.
 93→    pub active_environment: Option<String>,
 94→}
 95→
 96→impl<'a> WorkflowRunner<'a> {
 97→    /// Create a new workflow runner.
 98→    pub fn new(config: &'a BivvyConfig, steps: HashMap<String, ResolvedStep>) -> Self {
 99→        Self { config, steps }
100→    }
101→
102→    /// Run the specified workflow.
103→    pub fn run(
104→        &self,
105→        options: &RunOptions,
106→        context: &InterpolationContext,
107→        global_env: &HashMap<String, String>,
108→        project_root: &Path,
109→    ) -> Result<WorkflowResult> {
110→        self.run_with_progress(options, context, global_env, project_root, None, |_| {})
111→    }
112→
113→    /// Run the specified workflow with a progress callback.
114→    pub fn run_with_progress(
115→        &self,
116→        options: &RunOptions,
117→        context: &InterpolationContext,
118→        global_env: &HashMap<String, String>,
119→        project_root: &Path,
120→        mut gap_checker: Option<&mut GapChecker<'_>>,
121→        mut on_progress: impl FnMut(RunProgress<'_>),
122→    ) -> Result<WorkflowResult> {
123→        let start = Instant::now();
124→        let workflow_name = options.workflow.as_deref().unwrap_or("default");
125→
126→        // Build dependency graph
127→        let graph = self.build_graph(workflow_name)?;
128→
129→        // Compute skips
130→        let skipped = graph.compute_skips(&options.skip, options.skip_behavior);
131→
132→        // Get execution order
133→        let order = graph.topological_order()?;
134→
135→        // Filter by only_environments and --only/--skip
136→        let mut env_skipped: Vec<String> = Vec::new();
137→        let steps_to_run: Vec<_> = order
138→            .iter()
139→            .filter(|s| !skipped.contains(*s))
140→            .filter(|s| options.only.is_empty() || options.only.contains(*s))
141→            .filter(|s| {
142→                if let Some(step) = self.steps.get(*s) {
143→                    if !step.only_environments.is_empty() {
144→                        if let Some(ref active_env) = options.active_environment {
145→                            if !step.only_environments.iter().any(|e| e == active_env) {
146→                                env_skipped.push(s.to_string());
147→                                return false;
148→                            }
149→                        }
150→                    }
151→                }
152→                true
153→            })
154→            .cloned()
155→            .collect();
156→
157→        let total = steps_to_run.len();
158→
159→        // Report skipped steps
160→        for skip_name in &skipped {
161→            on_progress(RunProgress::StepSkipped { name: skip_name });
162→        }
163→        for skip_name in &env_skipped {
164→            on_progress(RunProgress::StepSkipped { name: skip_name });
165→        }
166→
167→        let mut results = Vec::new();
168→        let mut all_success = true;
169→        let mut failed_steps: HashSet<String> = HashSet::new();
170→
171→        for (index, step_name) in steps_to_run.iter().enumerate() {
172→            let step =
173→                self.steps
174→                    .get(step_name)
175→                    .ok_or_else(|| BivvyError::ConfigValidationError {
176→                        message: format!("Step '{}' not found in resolved steps", step_name),
177→                    })?;
178→
179→            // Check if any dependency failed
180→            if step.depends_on.iter().any(|dep| failed_steps.contains(dep)) {
181→                on_progress(RunProgress::StepSkipped { name: step_name });
182→                all_success = false;
183→                failed_steps.insert(step_name.clone());
184→                continue;
185→            }
186→
187→            // Check requirement gaps (non-UI: any blocking gap is an error)
188→            if let Some(ref mut checker) = gap_checker {
189→                let provided = if options.provided_requirements.is_empty() {
190→                    None
191→                } else {
192→                    Some(&options.provided_requirements)
193→                };
194→                let gaps = checker.check_step(step, provided);
195→                let blocking: Vec<_> = gaps
196→                    .iter()
197→                    .filter(|g| !g.status.is_satisfied() && !g.status.can_proceed())
198→                    .collect();
199→                if !blocking.is_empty() {
200→                    let names: Vec<_> = blocking.iter().map(|g| g.requirement.as_str()).collect();
201→                    return Err(BivvyError::RequirementMissing {
202→                        requirement: names.join(", "),
203→                        message: format!(
204→                            "Step '{}' requires: {}. Run 'bivvy lint' for details.",
205→                            step_name,
206→                            names.join(", ")
207→                        ),
208→                    });
209→                }
210→            }
211→
212→            on_progress(RunProgress::StepStarting {
213→                name: step_name,
214→                index,
215→                total,
216→            });
217→
218→            let exec_options = ExecutionOptions {
219→                force: options.force.contains(step_name),
220→                dry_run: options.dry_run,
221→                capture_output: true,
222→                ..Default::default()
223→            };
224→
225→            let step_start = Instant::now();
226→            let result =
227→                match execute_step(step, project_root, context, global_env, &exec_options, None) {
228→                    Ok(result) => result,
229→                    Err(e) => {
230→                        warn!("Step '{}' errored: {}", step_name, e);
231→                        StepResult::failure(step_name, step_start.elapsed(), e.to_string(), None)
232→                    }
233→                };
234→
235→            on_progress(RunProgress::StepFinished {
236→                name: step_name,
237→                result: &result,
238→            });
239→
240→            let status = result.status();
241→
242→            results.push(result);
243→
244→            if status == StepStatus::Failed {
245→                all_success = false;
246→                if !step.allow_failure {
247→                    failed_steps.insert(step_name.clone());
248→                }
249→            }
250→        }
251→
252→        let mut all_skipped: Vec<String> = skipped.into_iter().collect();
253→        all_skipped.extend(env_skipped);
254→
255→        Ok(WorkflowResult {
256→            workflow: workflow_name.to_string(),
257→            steps: results,
258→            skipped: all_skipped,
259→            duration: start.elapsed(),
260→            success: all_success,
261→            aborted: false,
262→        })
263→    }
264→
265→    /// Run the specified workflow with direct UI interaction.
266→    ///
267→    /// Unlike `run_with_progress`, this method takes a `UserInterface` directly
268→    /// and handles interactive prompts for completed steps and sensitive steps.
269→    /// An optional `GapChecker` enables requirement gap detection before step execution.
270→    #[allow(clippy::too_many_arguments)]
271→    pub fn run_with_ui(
272→        &self,
273→        options: &RunOptions,
274→        context: &InterpolationContext,
275→        global_env: &HashMap<String, String>,
276→        project_root: &Path,
277→        workflow_non_interactive: bool,
278→        step_overrides: &HashMap<String, StepOverride>,
279→        mut gap_checker: Option<&mut GapChecker<'_>>,
280→        ui: &mut dyn UserInterface,
281→    ) -> Result<WorkflowResult> {
282→        let start = Instant::now();
283→        let workflow_name = options.workflow.as_deref().unwrap_or("default");
284→
285→        // Build dependency graph
286→        let graph = self.build_graph(workflow_name)?;
287→
288→        // Compute skips
289→        let skipped = graph.compute_skips(&options.skip, options.skip_behavior);
290→
291→        // Get execution order
292→        let order = graph.topological_order()?;
293→
294→        // Filter by only_environments
295→        let mut env_skipped: Vec<String> = Vec::new();
296→        let steps_to_run: Vec<_> = order
297→            .iter()
298→            .filter(|s| !skipped.contains(*s))
299→            .filter(|s| options.only.is_empty() || options.only.contains(*s))
300→            .filter(|s| {
301→                if let Some(step) = self.steps.get(*s) {
302→                    if !step.only_environments.is_empty() {
303→                        if let Some(ref active_env) = options.active_environment {
304→                            if !step.only_environments.iter().any(|e| e == active_env) {
305→                                env_skipped.push(s.to_string());
306→                                return false;
307→                            }
308→                        }
309→                    }
310→                }
311→                true
312→            })
313→            .cloned()
314→            .collect();
315→
316→        let total = steps_to_run.len();
317→        let theme = BivvyTheme::new();
318→
319→        // Report skipped steps (from --skip flag)
320→        for skip_name in &skipped {
321→            ui.message(&format!(
322→                "    {}",
323→                theme.format_skipped(&format!("{} skipped", skip_name))
324→            ));
325→        }
326→        for skip_name in &env_skipped {
327→            ui.message(&format!(
328→                "    {}",
329→                theme.format_skipped(&format!(
330→                    "{} skipped (not in {} environment)",
331→                    skip_name,
332→                    options.active_environment.as_deref().unwrap_or("unknown")
333→                ))
334→            ));
335→        }
336→
337→        let interactive = ui.is_interactive() && !workflow_non_interactive;
338→        let installer_ctx = installer::default_context();
339→
340→        let mut results = Vec::new();
341→        let mut all_success = true;
342→        let mut failed_steps: HashSet<String> = HashSet::new();
343→        let mut workflow_aborted = false;
344→
345→        for (index, step_name) in steps_to_run.iter().enumerate() {
346→            let step =
347→                self.steps
348→                    .get(step_name)
349→                    .ok_or_else(|| BivvyError::ConfigValidationError {
350→                        message: format!("Step '{}' not found in resolved steps", step_name),
351→                    })?;
352→
353→            // Blank line between steps
354→            if index > 0 {
355→                ui.message("");
356→            }
357→
358→            // Format step display with numbering: "[1/7] name — title" or "[1/7] name"
359→            let step_number = format!("[{}/{}]", index + 1, total);
360→            let step_display = if *step_name == step.title {
361→                format!(
362→                    "{} {}",
363→                    theme.step_number.apply_to(&step_number),
364→                    theme.step_title.apply_to(step_name)
365→                )
366→            } else {
367→                format!(
368→                    "{} {} {} {}",
369→                    theme.step_number.apply_to(&step_number),
370→                    theme.step_title.apply_to(step_name),
371→                    theme.dim.apply_to("—"),
372→                    theme.dim.apply_to(&step.title)
373→                )
374→            };
375→
376→            // Check if any dependency failed
377→            if step.depends_on.iter().any(|dep| failed_steps.contains(dep)) {
378→                ui.message(&step_display);
379→                ui.message(&format!(
380→                    "    {}",
381→                    StatusKind::Blocked.format(&theme, "Blocked (dependency failed)")
382→                ));
383→                ui.show_workflow_progress(index + 1, total, start.elapsed());
384→                all_success = false;
385→                failed_steps.insert(step_name.clone());
386→                continue;
387→            }
388→
389→            // Check requirement gaps before proceeding
390→            if let Some(ref mut checker) = gap_checker {
391→                let provided = if options.provided_requirements.is_empty() {
392→                    None
393→                } else {
394→                    Some(&options.provided_requirements)
395→                };
396→                let gaps = checker.check_step(step, provided);
397→                if !gaps.is_empty() {
398→                    let can_proceed =
399→                        installer::handle_gaps(&gaps, checker, ui, interactive, &installer_ctx)?;
400→                    if !can_proceed {
401→                        ui.message(&step_display);
402→                        ui.message(&format!(
403→                            "    {}",
404→                            StatusKind::Skipped.format(&theme, "Skipped (requirement not met)")
405→                        ));
406→                        ui.show_workflow_progress(index + 1, total, start.elapsed());
407→                        continue;
408→                    }
409→                }
410→            }
411→
412→            // Resolve effective prompt_if_complete (step-level, possibly overridden)
413→            let effective_prompt_if_complete = step_overrides
414→                .get(step_name)
415→                .and_then(|o| o.prompt_if_complete)
416→                .unwrap_or(step.prompt_if_complete);
417→
418→            let mut needs_force = options.force.contains(step_name);
419→            let mut already_prompted = false;
420→            let mut had_prompt = false;
421→
422→            // Check if already complete (unless forced)
423→            if !needs_force && !options.dry_run {
424→                if let Some(ref check) = step.completed_check {
425→                    let check_result = run_check(check, project_root);
426→                    if check_result.complete {
427→                        if interactive && effective_prompt_if_complete {
428→                            if step.skippable {
429→                                // Ask if they want to re-run (prompt IS the step header)
430→                                let prompt = Prompt {
431→                                    key: format!("rerun_{}", step_name),
432→                                    question: format!("Already complete. Re-run {}?", step_display),
433→                                    prompt_type: PromptType::Select {
434→                                        options: vec![
435→                                            PromptOption {
436→                                                label: "No (n)".to_string(),
437→                                                value: "no".to_string(),
438→                                            },
439→                                            PromptOption {
440→                                                label: "Yes (y)".to_string(),
441→                                                value: "yes".to_string(),
442→                                            },
443→                                        ],
444→                                    },
445→                                    default: Some("no".to_string()),
446→                                };
447→
448→                                let answer = ui.prompt(&prompt)?;
449→                                if answer.as_string() != "yes" {
450→                                    let reason = check_result.short_description();
451→                                    ui.message(&format!(
452→                                        "    {}",
453→                                        theme.format_skipped(&format!("Skipped ({})", reason))
454→                                    ));
455→                                    results.push(StepResult::skipped(&step.name, check_result));
456→                                    continue;
457→                                }
458→                                // User wants to re-run
459→                                needs_force = true;
460→                                already_prompted = true;
461→                                had_prompt = true;
462→                            } else {
463→                                // Not skippable, inform and re-run
464→                                ui.message(&step_display);
465→                                ui.message("    Re-running (not skippable)");
466→                                needs_force = true;
467→                            }
468→                        } else {
469→                            // Not interactive or prompt_if_complete is false: silently skip
470→                            ui.message(&step_display);
471→                            let reason = check_result.short_description();
472→                            ui.message(&format!(
473→                                "    {}",
474→                                theme.format_skipped(&format!("Skipped ({})", reason))
475→                            ));
476→                            results.push(StepResult::skipped(&step.name, check_result));
477→                            continue;
478→                        }
479→                    }
480→                }
481→            }
482→
483→            // In interactive mode, prompt before running skippable steps
484→            // (skip if already prompted by completed check)
485→            if interactive && step.skippable && !already_prompted {
486→                let prompt = Prompt {
487→                    key: format!("run_{}", step_name),
488→                    question: format!("{}?", step_display),
489→                    prompt_type: PromptType::Select {
490→                        options: vec![
491→                            PromptOption {
492→                                label: "Yes (y)".to_string(),
493→                                value: "yes".to_string(),
494→                            },
495→                            PromptOption {
496→                                label: "No (n)".to_string(),
497→                                value: "no".to_string(),
498→                            },
499→                        ],
500→                    },

  1→//! Interactive terminal UI.
  2→
  3→use console::Term;
  4→use std::io::Write;
  5→use std::time::Duration;
  6→
  7→use crate::error::Result;
  8→
  9→use super::progress::format_duration;
 10→use super::{
 11→    prompt_user, should_use_colors, BivvyTheme, NonInteractiveUI, OutputMode, ProgressSpinner,
 12→    Prompt, PromptResult, RunSummary, SpinnerHandle, UserInterface,
 13→};
 14→
 15→/// Interactive terminal UI implementation.
 16→pub struct TerminalUI {
 17→    term: Term,
 18→    theme: BivvyTheme,
 19→    mode: OutputMode,
 20→}
 21→
 22→impl TerminalUI {
 23→    /// Create a new terminal UI.
 24→    pub fn new(mode: OutputMode) -> Self {
 25→        let theme = if should_use_colors() {
 26→            BivvyTheme::new()
 27→        } else {
 28→            BivvyTheme::plain()
 29→        };
 30→
 31→        Self {
 32→            term: Term::stdout(),
 33→            theme,
 34→            mode,
 35→        }
 36→    }
 37→}
 38→
 39→impl UserInterface for TerminalUI {
 40→    fn output_mode(&self) -> OutputMode {
 41→        self.mode
 42→    }
 43→
 44→    fn message(&mut self, msg: &str) {
 45→        if self.mode.shows_status() {
 46→            writeln!(self.term, "{}", msg).ok();
 47→        }
 48→    }
 49→
 50→    fn success(&mut self, msg: &str) {
 51→        if self.mode.shows_status() {
 52→            writeln!(self.term, "{}", self.theme.format_success(msg)).ok();
 53→        }
 54→    }
 55→
 56→    fn warning(&mut self, msg: &str) {
 57→        if self.mode.shows_status() {
 58→            writeln!(self.term, "{}", self.theme.format_warning(msg)).ok();
 59→        }
 60→    }
 61→
 62→    fn error(&mut self, msg: &str) {
 63→        writeln!(self.term, "{}", self.theme.format_error(msg)).ok();
 64→    }
 65→
 66→    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
 67→        prompt_user(prompt, &self.term)
 68→    }
 69→
 70→    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle> {
 71→        if self.mode.shows_spinners() {
 72→            Box::new(ProgressSpinner::new(message))
 73→        } else {
 74→            Box::new(ProgressSpinner::hidden())
 75→        }
 76→    }
 77→
 78→    fn start_spinner_indented(&mut self, message: &str, indent: usize) -> Box<dyn SpinnerHandle> {
 79→        if self.mode.shows_spinners() {
 80→            Box::new(ProgressSpinner::with_indent(message, indent))
 81→        } else {
 82→            Box::new(ProgressSpinner::hidden())
 83→        }
 84→    }
 85→
 86→    fn show_header(&mut self, title: &str) {
 87→        if self.mode.shows_status() {
 88→            writeln!(self.term, "\n{}\n", self.theme.format_header(title)).ok();
 89→        }
 90→    }
 91→
 92→    fn show_progress(&mut self, current: usize, total: usize) {
 93→        if self.mode.shows_status() {
 94→            writeln!(
 95→                self.term,
 96→                "{}",
 97→                self.theme.dim.apply_to(format!("[{}/{}]", current, total))
 98→            )
 99→            .ok();
100→        }
101→    }
102→
103→    fn is_interactive(&self) -> bool {
104→        self.term.is_term()
105→    }
106→
107→    fn set_output_mode(&mut self, mode: OutputMode) {
108→        self.mode = mode;
109→    }
110→
111→    fn show_run_header(
112→        &mut self,
113→        app_name: &str,
114→        workflow: &str,
115→        step_count: usize,
116→        version: &str,
117→    ) {
118→        if self.mode.shows_status() {
119→            let step_label = if step_count == 1 { "step" } else { "steps" };
120→            writeln!(
121→                self.term,
122→                "\n{} {} {} {} {} {}\n",
123→                self.theme.header.apply_to("⛺"),
124→                self.theme.highlight.apply_to(app_name),
125→                self.theme.dim.apply_to(format!("v{}", version)),
126→                self.theme.dim.apply_to("·"),
127→                self.theme.dim.apply_to(format!("{} workflow", workflow)),
128→                self.theme
129→                    .dim
130→                    .apply_to(format!("· {} {}", step_count, step_label)),
131→            )
132→            .ok();
133→        }
134→    }
135→
136→    fn show_workflow_progress(&mut self, current: usize, total: usize, elapsed: Duration) {
137→        if self.mode.shows_status() {
138→            let filled = if total > 0 { (current * 16) / total } else { 0 };
139→            let empty = 16 - filled;
140→            let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty),);
141→            writeln!(
142→                self.term,
143→                "  {} {}/{} steps {} {}",
144→                self.theme.info.apply_to(format!("[{}]", bar)),
145→                current,
146→                total,
147→                self.theme.dim.apply_to("·"),
148→                self.theme
149→                    .duration
150→                    .apply_to(format!("{} elapsed", format_duration(elapsed))),
151→            )
152→            .ok();
153→        }
154→    }
155→
156→    fn show_hint(&mut self, hint: &str) {
157→        if self.mode.shows_status() {
158→            writeln!(self.term, "  {}", self.theme.hint.apply_to(hint)).ok();
159→            writeln!(self.term).ok();
160→        }
161→    }
162→
163→    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>) {
164→        let b = &self.theme.border;
165→        let top = format!(
166→            "    {} {}",
167→            b.apply_to("┌─"),
168→            b.apply_to("Command ──────────────────────────")
169→        );
170→        let cmd_line = format!(
171→            "    {} {}",
172→            b.apply_to("│"),
173→            self.theme.command.apply_to(command)
174→        );
175→        writeln!(self.term, "{}", top).ok();
176→        writeln!(self.term, "{}", cmd_line).ok();
177→
178→        if !output.is_empty() {
179→            writeln!(
180→                self.term,
181→                "    {} {}",
182→                b.apply_to("├─"),
183→                b.apply_to("Output ───────────────────────────")
184→            )
185→            .ok();
186→            for line in output.lines() {
187→                writeln!(self.term, "    {} {}", b.apply_to("│"), line).ok();
188→            }
189→        }
190→
191→        writeln!(
192→            self.term,
193→            "    {}",
194→            b.apply_to("└────────────────────────────────────")
195→        )
196→        .ok();
197→
198→        if let Some(h) = hint {
199→            writeln!(self.term).ok();
200→            writeln!(
201→                self.term,
202→                "    {} {}",
203→                self.theme.hint.apply_to("Hint:"),
204→                self.theme.hint.apply_to(h)
205→            )
206→            .ok();
207→        }
208→    }
209→
210→    fn show_run_summary(&mut self, summary: &RunSummary) {
211→        if !self.mode.shows_status() {
212→            return;
213→        }
214→
215→        let b = &self.theme.border;
216→
217→        writeln!(self.term).ok();
218→        writeln!(
219→            self.term,
220→            "  {} {}",
221→            b.apply_to("┌─"),
222→            b.apply_to("Summary ──────────────────────────")
223→        )
224→        .ok();
225→
226→        for step in &summary.step_results {
227→            let icon = step.status.styled(&self.theme);
228→            let duration_str = step.duration.map(format_duration).unwrap_or_default();
229→            let detail_str = step.detail.as_deref().unwrap_or("");
230→
231→            let right_side = if !duration_str.is_empty() {
232→                self.theme.duration.apply_to(duration_str).to_string()
233→            } else if !detail_str.is_empty() {
234→                self.theme.dim.apply_to(detail_str).to_string()
235→            } else {
236→                String::new()
237→            };
238→
239→            writeln!(
240→                self.term,
241→                "  {} {} {:<20} {}",
242→                b.apply_to("│"),
243→                icon,
244→                step.name,
245→                right_side,
246→            )
247→            .ok();
248→        }
249→
250→        // Footer
251→        writeln!(
252→            self.term,
253→            "  {}",
254→            b.apply_to("├────────────────────────────────────")
255→        )
256→        .ok();
257→        writeln!(
258→            self.term,
259→            "  {} Total: {} {} {} run {} {} skipped",
260→            b.apply_to("│"),
261→            self.theme
262→                .duration
263→                .apply_to(format_duration(summary.total_duration)),
264→            self.theme.dim.apply_to("·"),
265→            summary.steps_run,
266→            self.theme.dim.apply_to("·"),
267→            summary.steps_skipped,
268→        )
269→        .ok();
270→        writeln!(
271→            self.term,
272→            "  {}",
273→            b.apply_to("└────────────────────────────────────")
274→        )
275→        .ok();
276→    }
277→}
278→
279→/// Create the appropriate UI based on context.
280→pub fn create_ui(interactive: bool, mode: OutputMode) -> Box<dyn UserInterface> {
281→    if interactive && Term::stdout().is_term() {
282→        Box::new(TerminalUI::new(mode))
283→    } else {
284→        Box::new(NonInteractiveUI::new(mode))
285→    }
286→}
