  1→//! Dependency graph for step execution ordering.
  2→
  3→use std::collections::{HashMap, HashSet, VecDeque};
  4→
  5→use crate::error::{BivvyError, Result};
  6→
  7→/// How to handle skipping a step that has dependents.
  8→#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
  9→pub enum SkipBehavior {
 10→    /// Skip the step and all its dependents.
 11→    #[default]
 12→    SkipWithDependents,
 13→    /// Don't skip - run the step anyway.
 14→    RunAnyway,
 15→    /// Skip only this step, attempt to run dependents.
 16→    SkipOnly,
 17→}
 18→
 19→/// Represents the dependency relationships between steps.
 20→#[derive(Debug, Clone)]
 21→pub struct DependencyGraph {
 22→    /// Map of step name to its direct dependencies.
 23→    dependencies: HashMap<String, HashSet<String>>,
 24→    /// Map of step name to steps that depend on it.
 25→    dependents: HashMap<String, HashSet<String>>,
 26→    /// All step names in the graph.
 27→    steps: HashSet<String>,
 28→}
 29→
 30→impl DependencyGraph {
 31→    /// Create a new dependency graph builder.
 32→    pub fn builder() -> DependencyGraphBuilder {
 33→        DependencyGraphBuilder::new()
 34→    }
 35→
 36→    /// Get the direct dependencies of a step.
 37→    pub fn dependencies_of(&self, step: &str) -> Option<&HashSet<String>> {
 38→        self.dependencies.get(step)
 39→    }
 40→
 41→    /// Get steps that depend on the given step.
 42→    pub fn dependents_of(&self, step: &str) -> Option<&HashSet<String>> {
 43→        self.dependents.get(step)
 44→    }
 45→
 46→    /// Check if a step exists in the graph.
 47→    pub fn contains(&self, step: &str) -> bool {
 48→        self.steps.contains(step)
 49→    }
 50→
 51→    /// Get all step names.
 52→    pub fn steps(&self) -> &HashSet<String> {
 53→        &self.steps
 54→    }
 55→
 56→    /// Get the number of steps in the graph.
 57→    pub fn len(&self) -> usize {
 58→        self.steps.len()
 59→    }
 60→
 61→    /// Check if the graph is empty.
 62→    pub fn is_empty(&self) -> bool {
 63→        self.steps.is_empty()
 64→    }
 65→
 66→    /// Returns steps in topological order (dependencies before dependents).
 67→    ///
 68→    /// Returns an error if a cycle is detected.
 69→    pub fn topological_order(&self) -> Result<Vec<String>> {
 70→        // Count incoming edges for each node
 71→        let mut in_degree: HashMap<String, usize> = HashMap::new();
 72→        for step in &self.steps {
 73→            in_degree.insert(
 74→                step.clone(),
 75→                self.dependencies.get(step).map_or(0, |d| d.len()),
 76→            );
 77→        }
 78→
 79→        // Start with nodes that have no dependencies
 80→        let mut queue: VecDeque<String> = in_degree
 81→            .iter()
 82→            .filter(|(_, &degree)| degree == 0)
 83→            .map(|(step, _)| step.clone())
 84→            .collect();
 85→
 86→        let mut result = Vec::with_capacity(self.steps.len());
 87→
 88→        while let Some(step) = queue.pop_front() {
 89→            result.push(step.clone());
 90→
 91→            // Reduce in-degree for all dependents
 92→            if let Some(dependents) = self.dependents.get(&step) {
 93→                for dependent in dependents {
 94→                    if let Some(degree) = in_degree.get_mut(dependent) {
 95→                        *degree -= 1;
 96→                        if *degree == 0 {
 97→                            queue.push_back(dependent.clone());
 98→                        }
 99→                    }
100→                }
101→            }
102→        }
103→
104→        // If we haven't processed all nodes, there's a cycle
105→        if result.len() != self.steps.len() {
106→            let remaining: Vec<_> = in_degree
107→                .iter()
108→                .filter(|(_, &d)| d > 0)
109→                .map(|(s, _)| s.clone())
110→                .collect();
111→
112→            return Err(BivvyError::CircularDependency {
113→                cycle: remaining.join(" -> "),
114→            });
115→        }
116→
117→        Ok(result)
118→    }
119→
120→    /// Find a cycle in the graph, returning the path if one exists.
121→    pub fn find_cycle(&self) -> Option<Vec<String>> {
122→        #[derive(Clone, Copy, PartialEq)]
123→        enum State {
124→            Unvisited,
125→            Visiting,
126→            Visited,
127→        }
128→
129→        let mut state: HashMap<&str, State> = self
130→            .steps
131→            .iter()
132→            .map(|s| (s.as_str(), State::Unvisited))
133→            .collect();
134→
135→        let mut path: Vec<String> = Vec::new();
136→
137→        fn dfs<'a>(
138→            node: &'a str,
139→            graph: &'a DependencyGraph,
140→            state: &mut HashMap<&'a str, State>,
141→            path: &mut Vec<String>,
142→        ) -> Option<Vec<String>> {
143→            state.insert(node, State::Visiting);
144→            path.push(node.to_string());
145→
146→            if let Some(deps) = graph.dependencies.get(node) {
147→                for dep in deps {
148→                    match state.get(dep.as_str()) {
149→                        Some(State::Visiting) => {
150→                            // Found cycle - build the cycle path
151→                            let cycle_start = path.iter().position(|s| s == dep).unwrap();
152→                            let mut cycle: Vec<String> = path[cycle_start..].to_vec();
153→                            cycle.push(dep.clone());
154→                            return Some(cycle);
155→                        }
156→                        Some(State::Unvisited) | None => {
157→                            if let Some(cycle) = dfs(dep, graph, state, path) {
158→                                return Some(cycle);
159→                            }
160→                        }
161→                        Some(State::Visited) => {}
162→                    }
163→                }
164→            }
165→
166→            path.pop();
167→            state.insert(node, State::Visited);
168→            None
169→        }
170→
171→        for step in &self.steps {
172→            if state.get(step.as_str()) == Some(&State::Unvisited) {
173→                if let Some(cycle) = dfs(step, self, &mut state, &mut path) {
174→                    return Some(cycle);
175→                }
176→            }
177→        }
178→
179→        None
180→    }
181→
182→    /// Returns groups of steps that can execute in parallel.
183→    ///
184→    /// Each group contains steps whose dependencies are satisfied
185→    /// by all previous groups.
186→    pub fn parallel_groups(&self) -> Result<Vec<Vec<String>>> {
187→        // First ensure no cycles
188→        if let Some(cycle) = self.find_cycle() {
189→            return Err(BivvyError::CircularDependency {
190→                cycle: cycle.join(" -> "),
191→            });
192→        }
193→
194→        let mut groups: Vec<Vec<String>> = Vec::new();
195→        let mut completed: HashSet<String> = HashSet::new();
196→
197→        while completed.len() < self.steps.len() {
198→            let mut ready: Vec<String> = self
199→                .steps
200→                .iter()
201→                .filter(|s| !completed.contains(*s))
202→                .filter(|s| self.is_ready(s, &completed))
203→                .cloned()
204→                .collect();
205→
206→            if ready.is_empty() {
207→                break;
208→            }
209→
210→            // Sort for deterministic ordering
211→            ready.sort();
212→
213→            completed.extend(ready.iter().cloned());
214→            groups.push(ready);
215→        }
216→
217→        Ok(groups)
218→    }
219→
220→    /// Check if a step is ready to run given completed steps.
221→    pub fn is_ready(&self, step: &str, completed: &HashSet<String>) -> bool {
222→        match self.dependencies.get(step) {
223→            None => true,
224→            Some(deps) => deps.iter().all(|d| completed.contains(d)),
225→        }
226→    }
227→
228→    /// Get all transitive dependents of a step.
229→    ///
230→    /// Returns steps that depend on the given step, directly or indirectly.
231→    pub fn transitive_dependents(&self, step: &str) -> HashSet<String> {
232→        let mut result = HashSet::new();
233→        let mut to_visit = vec![step.to_string()];
234→
235→        while let Some(current) = to_visit.pop() {
236→            if let Some(dependents) = self.dependents.get(&current) {
237→                for dep in dependents {
238→                    if result.insert(dep.clone()) {
239→                        to_visit.push(dep.clone());
240→                    }
241→                }
242→            }
243→        }
244→
245→        result
246→    }
247→
248→    /// Given a set of steps to skip, compute which additional steps must be skipped.
249→    pub fn compute_skips(&self, skip: &HashSet<String>, behavior: SkipBehavior) -> HashSet<String> {
250→        match behavior {
251→            SkipBehavior::RunAnyway => HashSet::new(),
252→            SkipBehavior::SkipOnly => skip.clone(),
253→            SkipBehavior::SkipWithDependents => {
254→                let mut result = skip.clone();
255→                for step in skip {
256→                    result.extend(self.transitive_dependents(step));
257→                }
258→                result
259→            }
260→        }
261→    }
262→}
