264→/// Builder for constructing a DependencyGraph.
265→#[derive(Debug, Default)]
266→pub struct DependencyGraphBuilder {
267→    dependencies: HashMap<String, HashSet<String>>,
268→}
269→
270→impl DependencyGraphBuilder {
271→    /// Create a new builder.
272→    pub fn new() -> Self {
273→        Self::default()
274→    }
275→
276→    /// Add a step with its dependencies.
277→    pub fn add_step(mut self, name: impl Into<String>, depends_on: Vec<String>) -> Self {
278→        let name = name.into();
279→        self.dependencies
280→            .entry(name)
281→            .or_default()
282→            .extend(depends_on);
283→        self
284→    }
285→
286→    /// Build the dependency graph.
287→    ///
288→    /// Returns an error if any dependency references a non-existent step.
289→    pub fn build(self) -> Result<DependencyGraph> {
290→        // Collect all step names
291→        let steps: HashSet<String> = self.dependencies.keys().cloned().collect();
292→
293→        // Validate all dependencies exist
294→        for (step, deps) in &self.dependencies {
295→            for dep in deps {
296→                if !steps.contains(dep) {
297→                    return Err(BivvyError::ConfigValidationError {
298→                        message: format!("Step '{}' depends on unknown step '{}'", step, dep),
299→                    });
300→                }

500→                    },
501→                    default: Some("yes".to_string()),
502→                };
503→                let answer = ui.prompt(&prompt)?;
504→                if answer.as_string() != "yes" {
505→                    ui.message(&format!("    {}", theme.format_skipped("Skipped")));
506→                    results.push(StepResult::skipped(
507→                        &step.name,
508→                        crate::steps::CheckResult::complete("User declined"),
509→                    ));
510→                    continue;
511→                }
512→                had_prompt = true;
513→            }
514→
515→            // Show step name if no prompt was shown (non-interactive or non-skippable)
516→            if !had_prompt && !already_prompted {
517→                ui.message(&step_display);
518→            }
519→
520→            // Sensitive confirmation
521→            if step.sensitive && interactive {
522→                let prompt = Prompt {
523→                    key: format!("sensitive_{}", step_name),
524→                    question: "Handles sensitive data. Continue?".to_string(),
525→                    prompt_type: PromptType::Select {
526→                        options: vec![
527→                            PromptOption {
528→                                label: "Yes (y)".to_string(),
529→                                value: "yes".to_string(),
530→                            },
531→                            PromptOption {
532→                                label: "No (n)".to_string(),
533→                                value: "no".to_string(),
534→                            },
535→                        ],
536→                    },
537→                    default: Some("yes".to_string()),
538→                };
539→
540→                let answer = ui.prompt(&prompt)?;
541→                if answer.as_string() != "yes" {
542→                    if step.skippable {
543→                        ui.message(&format!(
544→                            "    {}",
545→                            theme.format_skipped("Skipped (declined sensitive step)")
546→                        ));
547→                        results.push(StepResult::skipped(
548→                            &step.name,
549→                            crate::steps::CheckResult::complete("User declined sensitive step"),
550→                        ));
551→                        continue;
552→                    } else {
553→                        return Err(BivvyError::StepExecutionError {
554→                            step: step_name.clone(),
555→                            message: format!(
556→                                "Step '{}' is sensitive and not skippable, but user declined",
557→                                step.title
558→                            ),
559→                        });
560→                    }
561→                }
562→                had_prompt = true;
563→            }
564→
565→            // Blank line before spinner when a prompt was shown (visual spacing)
566→            if had_prompt {
567→                ui.message("");
568→            }
569→
570→            // Build step context for pattern matching
571→            let step_ctx = StepContext {
572→                name: step_name,
573→                command: &step.command,
574→                requires: &step.requires,
575→                template: None,
576→            };
577→
578→            let mut retry_count: u32 = 0;
579→            let mut skipped_by_user = false;
580→            #[allow(unused_assignments)]
581→            let mut final_result: Option<StepResult> = None;
582→
583→            // Outer loop: step execution (retry/fix re-enter here)
584→            'step_execution: loop {
585→                // Fresh spinner per attempt
586→                let attempt_label = if retry_count > 0 {
587→                    format!(
588→                        "Running `{}`... (attempt {}/{})",
589→                        step.command,
590→                        retry_count + 1,
591→                        step.retry + 1
592→                    )
593→                } else {
594→                    format!("Running `{}`...", step.command)
595→                };
596→                let mut spinner = ui.start_spinner_indented(&attempt_label, 4);
597→
598→                // Create live output callback:
599→                // - Interactive mode: spinner-based ring buffer (3 lines verbose, 2 normal)
600→                // - Non-interactive verbose: print all output directly to stdout
601→                let output_mode = ui.output_mode();
602→                let output_callback = spinner
603→                    .progress_bar()
604→                    .and_then(|bar| {
605→                        let max_lines = match output_mode {
606→                            OutputMode::Verbose => 3,
607→                            OutputMode::Normal => 2,
608→                            _ => return None,
609→                        };
610→                        Some(live_output_callback(
611→                            bar,
612→                            attempt_label.clone(),
613→                            6,
614→                            max_lines,
615→                        ))
616→                    })
617→                    .or_else(|| {
618→                        // Non-interactive verbose: stream output directly
619→                        if output_mode == OutputMode::Verbose {
620→                            let cb: crate::shell::OutputCallback = Box::new(|line: OutputLine| {
621→                                let text = match &line {
622→                                    OutputLine::Stdout(s) => s.trim_end(),
623→                                    OutputLine::Stderr(s) => s.trim_end(),
624→                                };
625→                                if !text.is_empty() {
626→                                    println!("      {text}");
627→                                }
628→                            });
629→                            Some(cb)
630→                        } else {
631→                            None
632→                        }
633→                    });
634→
635→                let exec_options = ExecutionOptions {
636→                    force: needs_force,
637→                    dry_run: options.dry_run,
638→                    capture_output: output_callback.is_none(),
639→                    ..Default::default()
640→                };
641→
642→                let step_start = Instant::now();
643→                let result = match execute_step(
644→                    step,
645→                    project_root,
646→                    context,
647→                    global_env,
648→                    &exec_options,
649→                    output_callback,
650→                ) {
651→                    Ok(result) => result,
652→                    Err(e) => {
653→                        warn!("Step '{}' errored: {}", step_name, e);
654→                        StepResult::failure(step_name, step_start.elapsed(), e.to_string(), None)
655→                    }
656→                };
657→
658→                let duration_str = format_duration(result.duration);
659→
660→                match result.status() {
661→                    StepStatus::Completed => {
662→                        let detail = if retry_count > 0 {
663→                            Some(format!("succeeded on retry (attempt {})", retry_count + 1))
664→                        } else {
665→                            None
666→                        };
667→                        spinner.finish_success(&format!("{} ({})", step_name, duration_str));
668→                        let mut r = result;
669→                        r.recovery_detail = detail;
670→                        final_result = Some(r);
671→                        break 'step_execution;
672→                    }
673→                    StepStatus::Skipped => {
674→                        spinner.finish_skipped("Skipped");
675→                        final_result = Some(result);
676→                        break 'step_execution;
677→                    }
678→                    StepStatus::Failed => {
679→                        spinner.finish_error(&format!("Failed ({})", duration_str));
680→
681→                        // Build combined error output for pattern matching and display
682→                        let mut output_parts = Vec::new();
683→                        if let Some(ref err) = result.error {
684→                            output_parts.push(err.as_str());
685→                        }
686→                        if let Some(ref output) = result.output {
687→                            let trimmed = output.trim();
688→                            if !trimmed.is_empty() {
689→                                output_parts.push(trimmed);
690→                            }
691→                        }
692→                        let combined_output = output_parts.join("\n");
693→
694→                        // Match against pattern registry
695→                        let fix = patterns::find_fix(&combined_output, &step_ctx);
696→                        let hint = patterns::find_hint(&combined_output, &step_ctx);
697→
698→                        // Show error block — skip in non-interactive verbose
699→                        // where output was already streamed to stdout
700→                        let output_was_streamed =
701→                            !ui.is_interactive() && output_mode == OutputMode::Verbose;
702→                        if !output_was_streamed {
703→                            ui.show_error_block(&step.command, &combined_output, hint.as_deref());
704→                        }
705→
706→                        // allow_failure: record and move on, no recovery menu
707→                        if step.allow_failure {
708→                            final_result = Some(result);
709→                            break 'step_execution;
710→                        }
711→
712→                        // Auto-retry before showing recovery menu
713→                        if retry_count < step.retry {
714→                            retry_count += 1;
715→                            ui.message(&format!(
716→                                "    Retrying... (attempt {}/{})",
717→                                retry_count + 1,
718→                                step.retry + 1
719→                            ));
720→                            continue 'step_execution;
721→                        }
722→
723→                        // Non-interactive: no recovery menu
724→                        if !interactive {
725→                            final_result = Some(result);
726→                            break 'step_execution;
727→                        }
728→
729→                        // Safety: cap total attempts to prevent infinite loops
730→                        // (e.g., in tests where MockUI defaults to "retry")
731→                        if retry_count >= MAX_STEP_ATTEMPTS {
732→                            warn!(
733→                                "Step '{}' exceeded max recovery attempts ({})",
734→                                step_name, MAX_STEP_ATTEMPTS
735→                            );
736→                            final_result = Some(result);
737→                            break 'step_execution;
738→                        }
739→
740→                        // Interactive recovery menu
741→                        let has_hint = hint.is_some();
742→                        'recovery_menu: loop {
743→                            let action =
744→                                recovery::prompt_recovery(ui, step_name, fix.as_ref(), has_hint)?;
745→
746→                            match action {
747→                                RecoveryAction::Retry => {
748→                                    retry_count += 1;
749→                                    continue 'step_execution;
750→                                }
751→                                RecoveryAction::Fix(cmd) | RecoveryAction::CustomFix(cmd) => {
752→                                    if recovery::confirm_fix(ui, step_name, &cmd)? {
753→                                        let fix_ok =
754→                                            recovery::run_fix(&cmd, project_root, &step.env)?;
755→                                        if fix_ok {
756→                                            ui.message("    Fix command succeeded.");
757→                                        } else {
758→                                            ui.message("    Fix command failed.");
759→                                        }
760→                                        retry_count += 1;
761→                                        continue 'step_execution;
762→                                    } else {
763→                                        // User declined the fix — re-show recovery menu
764→                                        continue 'recovery_menu;
765→                                    }
766→                                }
767→                                RecoveryAction::Shell => {
768→                                    ui.message("    Dropping to debug shell (exit to return)...");
769→                                    crate::shell::debug::spawn_debug_shell(
770→                                        step_name,
771→                                        project_root,
772→                                        &step.env,
773→                                        global_env,
774→                                    )?;
775→                                    // After shell exit, re-show recovery menu
776→                                    continue 'recovery_menu;
777→                                }
778→                                RecoveryAction::Skip => {
779→                                    skipped_by_user = true;
780→                                    let mut r = result;
781→                                    r.recovery_detail =
782→                                        Some("skipped by user after failure".to_string());
783→                                    final_result = Some(r);
784→                                    break 'step_execution;
785→                                }
786→                                RecoveryAction::Abort => {
787→                                    workflow_aborted = true;
788→                                    let mut r = result;
789→                                    r.recovery_detail = Some("aborted by user".to_string());
790→                                    final_result = Some(r);
791→                                    break 'step_execution;
792→                                }
793→                            }
794→                        }
795→                    }
796→                    _ => {
797→                        final_result = Some(result);
798→                        break 'step_execution;
799→                    }

  1→//! Unified status vocabulary for consistent CLI output.
  2→//!
  3→//! `StatusKind` provides a single canonical set of status icons and
  4→//! colors used across all commands and display contexts. This replaces
  5→//! the previous split between theme-level symbols and display.rs brackets.
  6→
  7→use super::theme::BivvyTheme;
  8→
  9→/// Canonical status kinds used across all Bivvy output.
 10→#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
 11→pub enum StatusKind {
 12→    /// Operation completed successfully.
 13→    Success,
 14→    /// Operation failed.
 15→    Failed,
 16→    /// Operation was skipped.
 17→    Skipped,
 18→    /// Operation has not been run yet.
 19→    Pending,
 20→    /// Operation is currently running.
 21→    Running,
 22→    /// Operation is blocked (dependency failed).
 23→    Blocked,
 24→    /// Non-fatal warning.
 25→    Warning,
 26→}
 27→
 28→impl StatusKind {
 29→    /// Unicode icon for TTY output.
 30→    pub fn icon(self) -> &'static str {
 31→        match self {
 32→            Self::Success => "✓",
 33→            Self::Failed => "✗",
 34→            Self::Skipped => "○",
 35→            Self::Pending => "◌",
 36→            Self::Running => "◆",
 37→            Self::Blocked => "⊘",
 38→            Self::Warning => "⚠",
 39→        }
 40→    }
 41→
 42→    /// Bracketed text for non-TTY output.
 43→    pub fn bracketed(self) -> &'static str {
 44→        match self {
 45→            Self::Success => "[ok]",
 46→            Self::Failed => "[FAIL]",
 47→            Self::Skipped => "[skip]",
 48→            Self::Pending => "[pending]",
 49→            Self::Running => "[run]",
 50→            Self::Blocked => "[blocked]",
 51→            Self::Warning => "[warn]",
 52→        }
 53→    }
 54→
 55→    /// Styled icon string using the given theme.
 56→    pub fn styled(self, theme: &BivvyTheme) -> String {
 57→        let icon = self.icon();
 58→        match self {
 59→            Self::Success => theme.success.apply_to(icon).to_string(),
 60→            Self::Failed => theme.error.apply_to(icon).to_string(),
 61→            Self::Skipped => theme.dim.apply_to(icon).to_string(),
 62→            Self::Pending => theme.dim.apply_to(icon).to_string(),
 63→            Self::Running => theme.info.apply_to(icon).to_string(),
 64→            Self::Blocked => theme.warning.apply_to(icon).to_string(),
 65→            Self::Warning => theme.warning.apply_to(icon).to_string(),
 66→        }
 67→    }
 68→
 69→    /// Format a status line: styled icon + message.
 70→    pub fn format(self, theme: &BivvyTheme, msg: &str) -> String {
 71→        format!("{} {}", self.styled(theme), msg)
 72→    }
 73→
 74→    /// Format a status line for non-TTY: bracketed + message.
 75→    pub fn format_plain(self, msg: &str) -> String {
 76→        format!("{} {}", self.bracketed(), msg)
 77→    }
 78→}
 79→
 80→impl From<crate::state::StepStatus> for StatusKind {
 81→    fn from(status: crate::state::StepStatus) -> Self {
 82→        match status {
 83→            crate::state::StepStatus::Success => Self::Success,
 84→            crate::state::StepStatus::Failed => Self::Failed,
 85→            crate::state::StepStatus::Skipped => Self::Skipped,
 86→            crate::state::StepStatus::NeverRun => Self::Pending,
 87→        }
 88→    }
 89→}
 90→
 91→impl From<crate::steps::StepStatus> for StatusKind {
 92→    fn from(status: crate::steps::StepStatus) -> Self {
 93→        match status {
 94→            crate::steps::StepStatus::Pending => Self::Pending,
 95→            crate::steps::StepStatus::Running => Self::Running,
 96→            crate::steps::StepStatus::Completed => Self::Success,
 97→            crate::steps::StepStatus::Failed => Self::Failed,
 98→            crate::steps::StepStatus::Skipped => Self::Skipped,
 99→        }
100→    }
101→}
102→
103→impl From<crate::state::RunStatus> for StatusKind {
104→    fn from(status: crate::state::RunStatus) -> Self {
105→        match status {
106→            crate::state::RunStatus::Success => Self::Success,
107→            crate::state::RunStatus::Failed => Self::Failed,
108→            crate::state::RunStatus::Interrupted => Self::Warning,
109→        }
110→    }
111→}
