230→    fn all_variants_have_unique_brackets() {
231→        let brackets: Vec<&str> = [
232→            StatusKind::Success,
233→            StatusKind::Failed,
234→            StatusKind::Skipped,
235→            StatusKind::Pending,
236→            StatusKind::Running,
237→            StatusKind::Blocked,
238→            StatusKind::Warning,
239→        ]
240→        .iter()
241→        .map(|k| k.bracketed())
242→        .collect();
243→
244→        let mut unique = brackets.clone();
245→        unique.sort();
246→        unique.dedup();
247→        assert_eq!(
248→            unique.len(),
249→            brackets.len(),
250→            "All brackets should be unique"
251→        );
252→    }
253→}
